-- 0001_init.sql — exist.io metadata schema.
--
-- One migration creates the full stable schema. Later phases add typed helpers
-- over these tables; the shape is fixed here so the first migration is the
-- contract. All IDs use Origin prefixes (ns_, repo_, pr_, ...) generated by
-- pkg/idgen. Timestamps are RFC3339 UTC strings.

-- ============================================================================
-- Identity & tenancy (replaces Cursor teams with our own user/group model)
-- ============================================================================
CREATE TABLE users (
    id           TEXT PRIMARY KEY,           -- user_...
    email        TEXT NOT NULL UNIQUE,
    login        TEXT,
    name         TEXT,
    created_at   TEXT NOT NULL
);

CREATE TABLE groups (
    id           TEXT PRIMARY KEY,           -- grp_...
    namespace_id TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    description  TEXT,
    created_at   TEXT NOT NULL,
    UNIQUE (namespace_id, name)
);

CREATE TABLE namespaces (
    id           TEXT PRIMARY KEY,           -- ns_...
    slug         TEXT NOT NULL UNIQUE,       -- the {owner} in URLs
    type         TEXT NOT NULL,              -- user | team
    name         TEXT,
    owner_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);

-- ============================================================================
-- Repositories
-- ============================================================================
CREATE TABLE repos (
    id                   TEXT PRIMARY KEY,   -- repo_...
    namespace_id         TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    name                 TEXT NOT NULL,
    full_name            TEXT NOT NULL,       -- {owner}/{name}
    default_branch       TEXT NOT NULL DEFAULT 'main',
    visibility           TEXT NOT NULL DEFAULT 'private',  -- internal | private
    clone_url            TEXT,
    web_url              TEXT,
    -- mirror state (Phase 5): source forge + sync status
    mirror_source        TEXT,                -- e.g. github URL
    mirror_source_id     TEXT,
    mirror_status        TEXT,                -- none | syncing | active | detached
    -- merge strategy flags
    allow_merge_commit   INTEGER NOT NULL DEFAULT 1,
    allow_squash_merge   INTEGER NOT NULL DEFAULT 1,
    delete_branch_on_merge INTEGER NOT NULL DEFAULT 0,
    created_at           TEXT NOT NULL,
    updated_at           TEXT NOT NULL,
    pushed_at            TEXT,
    UNIQUE (namespace_id, name)
);
CREATE INDEX idx_repos_namespace ON repos(namespace_id);

-- ============================================================================
-- Grants (namespace + repo). Principal is exactly one of user/group/teamGroup.
-- ============================================================================
CREATE TABLE grants (
    id            TEXT PRIMARY KEY,           -- internally generated
    scope         TEXT NOT NULL,              -- 'namespace' | 'repository'
    namespace_id  TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    repo_id       TEXT REFERENCES repos(id) ON DELETE CASCADE,  -- NULL for namespace grants
    -- principal: exactly one of the three id columns is non-NULL
    principal_kind TEXT NOT NULL,             -- 'user' | 'group' | 'teamGroup'
    user_id       TEXT,                       -- user_...
    group_id      TEXT,                       -- grp_...
    team_group    TEXT,                       -- 'members' | 'admins'
    permission    TEXT NOT NULL,              -- read|write|admin|custom | read|contributor|write|admin|custom
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    CHECK (principal_kind IN ('user','group','teamGroup')),
    CHECK (
        (principal_kind = 'user'      AND user_id IS NOT NULL AND group_id IS NULL AND team_group IS NULL) OR
        (principal_kind = 'group'     AND group_id IS NOT NULL AND user_id IS NULL AND team_group IS NULL) OR
        (principal_kind = 'teamGroup' AND team_group IS NOT NULL AND user_id IS NULL AND group_id IS NULL)
    ),
    CHECK (
        (scope = 'repository' AND repo_id IS NOT NULL) OR
        (scope = 'namespace'  AND repo_id IS NULL)
    )
);
CREATE INDEX idx_grants_repo ON grants(repo_id);
CREATE INDEX idx_grants_namespace ON grants(namespace_id);
-- One grant per (scope target, principal); upsert replaces the permission.
CREATE UNIQUE INDEX idx_grants_repo_principal ON grants(scope, repo_id, principal_kind, IFNULL(user_id,''), IFNULL(group_id,''), IFNULL(team_group,''));
CREATE UNIQUE INDEX idx_grants_ns_principal ON grants(scope, namespace_id, principal_kind, IFNULL(user_id,''), IFNULL(group_id,''), IFNULL(team_group,'')) WHERE repo_id IS NULL;

-- ============================================================================
-- Pull requests
-- ============================================================================
CREATE TABLE pull_requests (
    id             TEXT PRIMARY KEY,          -- pr_...
    repo_id        TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,
    number         INTEGER NOT NULL,
    state          TEXT NOT NULL,             -- open | closed
    draft          INTEGER NOT NULL DEFAULT 0,
    merged         INTEGER NOT NULL DEFAULT 0,
    title          TEXT NOT NULL,
    body           TEXT,
    head_ref       TEXT NOT NULL,
    head_sha       TEXT NOT NULL,
    base_ref       TEXT NOT NULL,
    base_sha       TEXT NOT NULL,
    author_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    merge_commit_sha TEXT,
    mergeable      TEXT,                       -- mergeable | stale | blocked (cached)
    additions      INTEGER NOT NULL DEFAULT 0,
    deletions      INTEGER NOT NULL DEFAULT 0,
    changed_files  INTEGER NOT NULL DEFAULT 0,
    auto_merge     INTEGER NOT NULL DEFAULT 0, -- PREVIEW
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    closed_at      TEXT,
    merged_at      TEXT,
    UNIQUE (repo_id, number)
);
CREATE INDEX idx_prs_repo_state ON pull_requests(repo_id, state);

CREATE TABLE pr_comments (
    id             TEXT PRIMARY KEY,
    repo_id        TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,
    pull_request_id TEXT NOT NULL REFERENCES pull_requests(id) ON DELETE CASCADE,
    author_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    body           TEXT NOT NULL,
    -- inline comment location (NULL for issue-level comments)
    path           TEXT,
    line           INTEGER,
    side           TEXT,                       -- LEFT | RIGHT
    commit_sha     TEXT,
    in_reply_to    TEXT REFERENCES pr_comments(id) ON DELETE CASCADE,  -- thread reply
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);
CREATE INDEX idx_pr_comments_pr ON pr_comments(pull_request_id);

CREATE TABLE pr_reviews (
    id             TEXT PRIMARY KEY,
    repo_id        TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,
    pull_request_id TEXT NOT NULL REFERENCES pull_requests(id) ON DELETE CASCADE,
    author_user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
    state          TEXT NOT NULL,             -- approved | changes_requested | commented | dismissed
    body           TEXT,
    commit_sha     TEXT,
    dismissed      INTEGER NOT NULL DEFAULT 0,
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL
);
CREATE INDEX idx_pr_reviews_pr ON pr_reviews(pull_request_id);

-- ============================================================================
-- Labels
-- ============================================================================
CREATE TABLE labels (
    id           TEXT PRIMARY KEY,
    namespace_id TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    color        TEXT,
    description  TEXT,
    created_at   TEXT NOT NULL,
    UNIQUE (namespace_id, name)
);

CREATE TABLE pr_labels (
    pull_request_id TEXT NOT NULL REFERENCES pull_requests(id) ON DELETE CASCADE,
    label_id        TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE,
    PRIMARY KEY (pull_request_id, label_id)
);

-- ============================================================================
-- Check runs & suites
-- ============================================================================
CREATE TABLE check_suites (
    id           TEXT PRIMARY KEY,            -- (suite id)
    repo_id      TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,
    sha          TEXT NOT NULL,
    base_sha     TEXT,
    key          TEXT,
    name         TEXT,
    details_url  TEXT,
    external_id  TEXT,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL
);
CREATE INDEX idx_check_suites_repo_sha ON check_suites(repo_id, sha);

CREATE TABLE check_runs (
    id              TEXT PRIMARY KEY,         -- cr_...
    repo_id         TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,
    check_suite_id  TEXT REFERENCES check_suites(id) ON DELETE CASCADE,
    sha             TEXT NOT NULL,
    base_sha        TEXT,
    key             TEXT,
    name            TEXT,
    status          TEXT NOT NULL,            -- queued | in_progress | completed | rerequested
    conclusion      TEXT,                     -- success | failure | neutral | cancelled | timed_out | action_required | stale | skipped
    details_url     TEXT,
    external_id     TEXT,
    output_title    TEXT,
    output_summary  TEXT,
    started_at      TEXT,
    completed_at    TEXT,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);
CREATE INDEX idx_check_runs_repo_sha ON check_runs(repo_id, sha);
CREATE INDEX idx_check_runs_suite ON check_runs(check_suite_id);

CREATE TABLE check_run_annotations (
    id            TEXT PRIMARY KEY,           -- cra_...
    check_run_id  TEXT NOT NULL REFERENCES check_runs(id) ON DELETE CASCADE,
    path          TEXT,
    start_line    INTEGER,
    end_line      INTEGER,
    annotation_level TEXT,                    -- notice | warning | failure
    message       TEXT,
    title         TEXT,
    raw_details   TEXT,
    created_at    TEXT NOT NULL
);
CREATE INDEX idx_annotations_run ON check_run_annotations(check_run_id);

-- ============================================================================
-- Rulesets
-- ============================================================================
CREATE TABLE rulesets (
    id                 TEXT PRIMARY KEY,
    repo_id            TEXT NOT NULL REFERENCES repos(id) ON DELETE CASCADE,
    name               TEXT NOT NULL,
    description        TEXT,
    enforcement        TEXT NOT NULL,          -- active | evaluate | disabled
    kind               TEXT NOT NULL,          -- merge_branch | push_branch | push_tag | push_repository
    included_ref_names TEXT,                   -- JSON array
    excluded_ref_names TEXT,                   -- JSON array
    rules              TEXT NOT NULL,          -- JSON array of {type, parameters}
    bypass_actors      TEXT,                   -- JSON array
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL
);
CREATE INDEX idx_rulesets_repo ON rulesets(repo_id);

-- ============================================================================
-- SSH certificate authorities + inbound IP allowlist (namespace-scoped)
-- ============================================================================
CREATE TABLE ssh_cas (
    id            TEXT PRIMARY KEY,           -- nsca_...
    namespace_id  TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    name          TEXT,
    key_type      TEXT NOT NULL,              -- e.g. ssh-ed25519
    public_key    TEXT NOT NULL,
    fingerprint   TEXT NOT NULL,              -- SHA256:...
    required      INTEGER NOT NULL DEFAULT 0, -- whether a CA cert is required
    created_at    TEXT NOT NULL
);
CREATE INDEX idx_ssh_cas_ns ON ssh_cas(namespace_id);

CREATE TABLE ip_allowlist (
    id            TEXT PRIMARY KEY,           -- nsip_...
    namespace_id  TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    cidr          TEXT NOT NULL,
    description   TEXT,
    enabled       INTEGER NOT NULL DEFAULT 1,
    created_at    TEXT NOT NULL,
    UNIQUE (namespace_id, cidr)
);
CREATE INDEX idx_ip_allowlist_ns ON ip_allowlist(namespace_id);

-- ============================================================================
-- Apps & installations
-- ============================================================================
CREATE TABLE apps (
    id              TEXT PRIMARY KEY,         -- app_...
    namespace_id    TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    display_name    TEXT NOT NULL,
    description     TEXT,
    website_url     TEXT,
    webhook_url     TEXT,
    events          TEXT,                     -- JSON array of event types
    default_scopes  TEXT,                     -- JSON array
    signing_key     TEXT,                     -- Ed25519 public key (PEM)
    visibility      TEXT NOT NULL DEFAULT 'private',
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL
);
CREATE INDEX idx_apps_ns ON apps(namespace_id);

CREATE TABLE installations (
    id            TEXT PRIMARY KEY,           -- inst_...
    app_id        TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
    namespace_id  TEXT NOT NULL REFERENCES namespaces(id) ON DELETE CASCADE,
    suspended     INTEGER NOT NULL DEFAULT 0,
    granted_scopes TEXT,                      -- JSON array
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    UNIQUE (app_id, namespace_id)
);
CREATE INDEX idx_installations_app ON installations(app_id);

-- ============================================================================
-- Webhook deliveries (event owed to an app). One row per (event, app).
-- ============================================================================
CREATE TABLE webhook_deliveries (
    id              TEXT PRIMARY KEY,         -- whd_... (also the webhook-id header)
    app_id          TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE,
    installation_id TEXT REFERENCES installations(id) ON DELETE CASCADE,
    event           TEXT NOT NULL,            -- e.g. pull_request.created
    payload         TEXT NOT NULL,            -- JSON body
    signature       TEXT NOT NULL,            -- v1ed base64
    delivered       INTEGER NOT NULL DEFAULT 0,
    delivered_at    TEXT,
    last_attempt_at TEXT,
    attempt_count   INTEGER NOT NULL DEFAULT 0,
    created_at      TEXT NOT NULL
);
CREATE INDEX idx_whd_app ON webhook_deliveries(app_id, delivered);
CREATE INDEX idx_whd_pending ON webhook_deliveries(delivered, created_at);
